"""Max Consecutive Ones III — sliding window with a zero budget.

Grow the window always; when it holds more than k zeros, walk `left` forward
until the budget is respected again.

Time: O(n)   Space: O(1)
"""
from typing import List


class Solution:
    def longestOnes(self, nums: List[int], k: int) -> int:
        left = zeros = best = 0
        for right, value in enumerate(nums):
            if value == 0:
                zeros += 1
            while zeros > k:
                if nums[left] == 0:
                    zeros -= 1
                left += 1
            best = max(best, right - left + 1)
        return best
